function localDay(d=new Date()){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
function TagInput({value,onChange}){const [draft,setDraft]=useState(value.join(', '));return <input aria-label="Document tags" value={draft} placeholder="research, ideas/books" onChange={e=>{setDraft(e.target.value);onChange([...new Set(e.target.value.split(',').map(t=>t.trim()).filter(Boolean))]);}}/>;}
function ViewHeading({eyebrow,title,description,actions}){return <div className="view-heading"><div><span className="eyebrow">{eyebrow}</span><h1>{title}</h1><p>{description}</p></div><div className="view-actions">{actions}</div></div>;}
function Outline({html}){const dom=new DOMParser().parseFromString(html,'text/html');const headings=[...dom.querySelectorAll('h1,h2,h3')];return <div className="outline">{headings.map((h,i)=><button key={i} className={h.tagName==='H3'?'indent':''} onClick={()=>document.querySelectorAll('.editor-pane .tiptap h1,.editor-pane .tiptap h2,.editor-pane .tiptap h3')[i]?.scrollIntoView({behavior:'smooth',block:'center'})}><span/>{h.textContent}</button>)}{!headings.length&&<p className="hint">Add headings to create an outline.</p>}</div>;}
function Stat({label,value,icon:Icon}){return <div className="stat"><span>{label}<Icon size={18}/></span><strong>{value}</strong></div>;}
function Graph({docs,allDocs,openDoc,savedPositions,onPositions}){
 const [positions,setPositions]=useState(savedPositions||{}),[zoom,setZoom]=useState(1),[drag,setDrag]=useState(null),svg=useRef();
 const [graphLimit,setGraphLimit]=useState(150);const totalDocs=docs.length;docs=docs.slice(0,graphLimit);const width=1000,height=660;
 const points=docs.map((d,i)=>({d,x:positions[d.id]?.x??width/2+Math.cos(i/Math.max(1,docs.length)*Math.PI*2-Math.PI/2)*(docs.length>1?Math.min(290,150+docs.length*8):0),y:positions[d.id]?.y??height/2+Math.sin(i/Math.max(1,docs.length)*Math.PI*2-Math.PI/2)*(docs.length>1?220:0)}));
 const edges=points.flatMap(p=>linkIds(p.d,allDocs).filter(id=>points.some(n=>n.d.id===id)).map(id=>({from:p,to:points.find(n=>n.d.id===id)})));
 return <section className="graph-view"><ViewHeading eyebrow="FOLLOW THE THREADS" title="Ideas in conversation" description="Every link is a connection. Drag notes to explore their relationships." actions={<><button className="button small" onClick={()=>{setPositions({});onPositions({});}}>Reset layout</button><button className="icon" aria-label="Zoom out graph" onClick={()=>setZoom(Math.max(.5,zoom-.15))}>−</button><span>{Math.round(zoom*100)}%</span><button className="icon" aria-label="Zoom in graph" onClick={()=>setZoom(Math.min(2,zoom+.15))}>+</button></>}/>{totalDocs>graphLimit&&<button className="text-button graph-more" onClick={()=>setGraphLimit(graphLimit+150)}>Showing {graphLimit} of {totalDocs} notes · load 150 more</button>}<div className="graph-canvas"><svg ref={svg} viewBox={`0 0 ${width} ${height}`} onPointerMove={e=>{if(!drag)return;const pt=svg.current.createSVGPoint();pt.x=e.clientX;pt.y=e.clientY;const loc=pt.matrixTransform(svg.current.getScreenCTM().inverse());setPositions(p=>({...p,[drag]:{x:(loc.x-width/2)/zoom+width/2,y:(loc.y-height/2)/zoom+height/2}}));}} onPointerUp={()=>{if(drag)onPositions(positions);setDrag(null);}} onPointerCancel={()=>setDrag(null)}><defs><pattern id="grid" width="24" height="24" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r="1" fill="var(--line)"/></pattern></defs><rect width="1000" height="660" fill="url(#grid)"/><g transform={`translate(${width/2} ${height/2}) scale(${zoom}) translate(${-width/2} ${-height/2})`}>{edges.map((e,i)=><path className="graph-edge" key={i} d={`M ${e.from.x} ${e.from.y} Q ${width/2} ${height/2} ${e.to.x} ${e.to.y}`}/>)}{points.map(({d,x,y})=><g className="graph-note" key={d.id} transform={`translate(${x} ${y})`} onDoubleClick={()=>openDoc(d.id)} onPointerDown={e=>{setDrag(d.id);e.currentTarget.setPointerCapture(e.pointerId);}} role="button" tabIndex="0" aria-label={'Open '+d.title} onKeyDown={e=>e.key==='Enter'&&openDoc(d.id)}><rect x="-105" y="-38" width="210" height="76" rx="10"/><circle cx="-83" cy="-14" r="4" fill={d.type==='card'?'#9293ff':d.type==='event'?'#79bfee':'#77d7b4'}/><text x="-70" y="-10" className="graph-type">{d.type==='card'?'KNOWLEDGE CARD':d.type==='event'?'STORY EVENT':'ARTICLE'}</text><text x="-83" y="14">{d.title.length>23?d.title.slice(0,22)+'…':d.title}</text></g>)}</g></svg><div className="graph-legend"><span><i style={{background:'#759787'}}/>Article</span><span><i style={{background:'#c5714c'}}/>Idea card</span><small>{docs.length} notes · {edges.length} links · double-click a note to open</small></div></div></section>;
}
function FileViewer({file,onPatch,onReveal,onExtract}){if(!file)return <p>File not found.</p>;const image=['png','jpg','jpeg','webp','gif'].includes(file.kind);return <><div className="file-viewer"><div className="file-preview">{file.kind==='pdf'?<iframe title={file.name} src={`folio-file://${file.id}/file`}/>:image?<img src={`folio-file://${file.id}/file`} alt={file.name}/>:<div className="empty"><FileText size={38}/><h3>{file.name}</h3><p>Open the library folder to read this text file.</p></div>}</div><div className="file-notes"><h3>{file.name}</h3><label>Reading notes<textarea rows="14" placeholder="Keep quotations, page numbers, and your own observations here…" value={file.notes||''} onChange={e=>onPatch({notes:e.target.value})}/></label><button className="button primary small" disabled={!file.notes} onClick={onExtract}><StickyNote size={15}/>Make a card from notes</button><button className="text-button" onClick={onReveal}><FolderOpen size={14}/>Reveal original file</button></div></div></>;}
function dialogTitle(type){if(type.startsWith('pro:'))return TOOL_TITLES[type.slice(4)]||'Writing tools';return ({closeUnsaved:'Unsaved changes',find:'Find and replace',insert:'Add to your page',importPreview:'Preview Atlas import',event:'Plan an event',renameItem:'Rename item',moveItem:'Move item',new:'Make space for an idea',project:'Project & writing goal',search:'Find your next thought',noteLink:'Connect a note',export:'Take your words with you',settings:'Make it your own',document:'Document options',trash:'Recover your writing',history:'A history of your words',compare:'Two pages, one desk',link:'Add a link',math:'Write an equation',table:'Shape your table',image:'An image for your page',reference:'A source worth keeping',bibliography:'Your bibliography',file:'Read, reflect, collect'})[type]||type;}
function dialogSubtitle(type){return ({new:'A longer piece or one small thought. Start anywhere.',project:'A place to gather related writing and ideas.',export:'Open formats, with no export limits.',settings:'A calm place to work, on your terms.',history:'Return to an earlier draft without losing the current one.',file:'Your source and your thoughts, side by side.'})[type];}








